import * as React from "react";

export type GamepadIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function GamepadIcon({ size = 20, ...props }: GamepadIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="3.5" y="8" width="17" height="9" rx="4.5" /><path d="M8 11v4M6 13h4M15.5 12h1M16.8 14.5h1" />
    </svg>
  );
}
